from pathlib import Path
root = Path(__file__).parent
checks = []
def check(name, ok): checks.append((name, bool(ok)))

service = (root/'src/medical-records/medical-records.service.ts').read_text()
controller = (root/'src/medical-records/medical-records.controller.ts').read_text()
module = (root/'src/medical-records/medical-records.module.ts').read_text()
app = (root/'src/app.module.ts').read_text()
data_source = (root/'src/database/data-source.ts').read_text()
prescription_entity = (root/'src/medical-records/medical-prescription.entity.ts').read_text()
lab_entity = (root/'src/medical-records/medical-lab-result.entity.ts').read_text()
prescription_dto = (root/'src/medical-records/dto/create-medical-prescription.dto.ts').read_text()
lab_dto = (root/'src/medical-records/dto/create-medical-lab-result.dto.ts').read_text()
migration = (root/'src/database/migrations/1734400000000-CreateStructuredPrescriptionsAndLabResults.ts').read_text()
docs = (root/'docs/phase-v83-structured-prescriptions-and-lab-results.md').read_text()

check('prescription entity stores structured medication JSON', 'medications' in prescription_entity and 'jsonb' in prescription_entity)
check('prescription includes dose frequency duration and instructions', all(x in prescription_entity for x in ['dosage', 'frequency', 'duration', 'instructions']))
check('prescription medication DTO validates each item', all(x in prescription_dto for x in ['ValidateNested', 'ArrayMinSize(1)', 'ArrayMaxSize(30)', 'Type(() => PrescriptionMedicationDto)']))
check('prescription medication count bounded to 30', 'ArrayMaxSize(30)' in prescription_dto)
check('prescription fields have length and type validation', all(x in prescription_dto for x in ['MaxLength(160)', 'MaxLength(120)', 'MaxLength(500)']))
check('lab result entity stores test value unit and range', all(x in lab_entity for x in ['testName', 'resultValue', 'unit', 'referenceRange']))
check('lab result supports bounded interpretation vocabulary', all(x in lab_dto for x in ['low', 'normal', 'high', 'critical', 'positive', 'negative', 'not_interpreted']))
check('lab DTO validates date and clinical text', 'IsDateString()' in lab_dto and 'MaxLength(3000)' in lab_dto)
check('doctor creation requires approved doctor', 'DoctorProfileStatus.APPROVED' in service and 'doctorAppointmentPatient' in service)
check('doctor creation requires own appointment', "where: { id: appointmentId, doctorId: actor.sub }" in service)
check('cancelled and no-show appointments blocked', 'AppointmentStatus.CANCELLED' in service and 'AppointmentStatus.NO_SHOW' in service)
check('guest beneficiaries without patient account blocked', 'المستفيد غير مرتبط بحساب مريض' in service)
check('prescription and record created transactionally', 'this.dataSource.transaction' in service and 'getRepository(MedicalPrescription)' in service)
check('lab result and record created transactionally', 'getRepository(MedicalLabResult)' in service and 'lab_result_create' in service)
check('generic medical record route cannot create unstructured prescriptions or lab results', 'أنشئ الوصفات ونتائج التحاليل من المسارات الطبية المنظمة' in service)
check('generic update cannot mutate structured medical document type', 'لا يمكن تعديل نوع المستند الطبي المنظم' in service and 'الوصفات ونتائج التحاليل تُنشأ من المسارات الطبية المنظمة' in service)
check('prescription type correctly assigned', 'recordType: MedicalRecordType.PRESCRIPTION' in service)
check('lab result type correctly assigned', 'recordType: MedicalRecordType.TEST_RESULT' in service)
check('structured reads require record access check', 'assertStructuredRecordAccess' in service and 'getPrescription' in service and 'getLabResult' in service)
check('doctor structured reads require approved status', 'حساب الطبيب غير معتمد حالياً' in service)
check('doctor reads require appointment relation or active consent', 'appointmentAccess' in service and 'c.revokedAt IS NULL AND c.expiresAt > NOW()' in service)
check('owner is explicitly denied structured medical access', "actor.role === UserRole.OWNER" in service and 'المالك لا يملك صلاحية السجلات الطبية' in service)
check('structured reads and writes audited', all(x in service for x in ['prescription_create', 'prescription_read', 'lab_result_create', 'lab_result_read']))
check('controller exposes prescription create and read routes', "@Post('prescriptions')" in controller and "@Get('prescriptions/:recordId')" in controller)
check('controller exposes lab result create and read routes', "@Post('lab-results')" in controller and "@Get('lab-results/:recordId')" in controller)
check('entities registered in feature module', 'MedicalPrescription' in module and 'MedicalLabResult' in module)
check('entities registered in app and migration data source', all(x in app and x in data_source for x in ['MedicalPrescription', 'MedicalLabResult']))
check('migration creates prescription and lab tables', 'CREATE TABLE "medical_prescriptions"' in migration and 'CREATE TABLE "medical_lab_results"' in migration)
check('migration adds foreign keys and unique record indexes', all(x in migration for x in ['REFERENCES "medical_records"', 'REFERENCES "appointments"', 'uq_medical_prescriptions_record', 'uq_medical_lab_results_record']))
check('migration constrains lab interpretation values', 'CK_medical_lab_interpretation' in migration)
check('synchronize remains disabled', 'synchronize:false' in app and 'synchronize:false' in data_source)
check('documentation records API migration and limitations', all(x in docs for x in ['POST /api/v1/medical-records/prescriptions', 'POST /api/v1/medical-records/lab-results', 'Run `1734400000000', 'PDF rendering']))

for name, ok in checks:
    print(('PASS' if ok else 'FAIL') + ' ' + name)
print(f'RESULT {sum(ok for _, ok in checks)}/{len(checks)}')
raise SystemExit(0 if all(ok for _, ok in checks) else 1)
